{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'fs'

// Read all input
const input = readFileSync(0, 'utf-8')

// Parse mode
const mode = process.argv[2]
if (!['merge', 'merge2', 'regions'].includes(mode)) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
  process.exit(2)
}

// Parse input documents
const parts = input.split('%%%\n')
if (parts.length !== 3) {
  process.stderr.write('error: expected three parts separated by %%%\n')
  process.exit(2)
}

// Parse each document - split on newlines and drop empty tail from trailing newline
function parseDocument(text) {
  if (text === '') return []
  const lines = text.split('\n')
  // Drop trailing empty line if it exists (from trailing newline)
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    return lines.slice(0, -1)
  }
  return lines
}

const mine = parseDocument(parts[0])
const base = parseDocument(parts[1])
const theirs = parseDocument(parts[2])

// LCS algorithm with early-match preference
function computeLCS(doc1, doc2) {
  // Find longest common subsequence with early-match preference
  // Returns array of [i, j] pairs indicating matched positions
  const matches = []
  let i = 0
  let j = 0

  while (i < doc1.length && j < doc2.length) {
    if (doc1[i] === doc2[j]) {
      // Lines match, take the match
      matches.push([i, j])
      i++
      j++
    } else {
      // Lines don't match, advance the side with longer remaining sequence
      const remainingDoc1 = doc1.length - i
      const remainingDoc2 = doc2.length - j

      if (remainingDoc1 > remainingDoc2) {
        i++
      } else if (remainingDoc2 > remainingDoc1) {
        j++
      } else {
        // When tied, prefer to advance doc2 (base in our case when comparing mine vs base)
        // But we need to think about this more carefully
        // The spec says: "preferring to advance the base when they tie"
        // In compareToBase, base is doc2, so we prefer j++
        j++
      }
    }
  }

  return matches
}

// Compare document to base and extract changes
function getChanges(doc, base, isTheirs) {
  const matches = computeLCS(doc, base)

  const changes = []
  let docIdx = 0
  let baseIdx = 0

  for (const [matchDoc, matchBase] of matches) {
    // Record the gap before this match as a change
    if (docIdx < matchDoc || baseIdx < matchBase) {
      changes.push({
        baseStart: baseIdx,
        baseEnd: matchBase,
        docStart: docIdx,
        docEnd: matchDoc,
        isTheirs
      })
    }
    docIdx = matchDoc + 1
    baseIdx = matchBase + 1
  }

  // Record any remaining gap as a change
  if (docIdx < doc.length || baseIdx < base.length) {
    changes.push({
      baseStart: baseIdx,
      baseEnd: base.length,
      docStart: docIdx,
      docEnd: doc.length,
      isTheirs
    })
  }

  return changes
}

// Get changes from both sides
const mineChanges = getChanges(mine, base, false)
const theirsChanges = getChanges(theirs, base, true)

// Merge changes by base position
const allChanges = [...mineChanges, ...theirsChanges]
  .sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    // mine changes before theirs when starting at same place
    if (a.isTheirs && !b.isTheirs) return 1
    if (!a.isTheirs && b.isTheirs) return -1
    return 0
  })

// Group overlapping changes into regions
const regions = []
let i = 0

while (i < allChanges.length) {
  const regionStart = allChanges[i].baseStart
  let regionEnd = allChanges[i].baseEnd

  const regionChanges = [allChanges[i]]
  i++

  // Absorb overlapping changes
  while (i < allChanges.length && allChanges[i].baseStart <= regionEnd) {
    regionEnd = Math.max(regionEnd, allChanges[i].baseEnd)
    regionChanges.push(allChanges[i])
    i++
  }

  regions.push({
    baseStart: regionStart,
    baseEnd: regionEnd,
    changes: regionChanges
  })
}

// Resolve each region
const resolvedRegions = []
let hasConflict = false

for (const region of regions) {
  const mineChangesInRegion = region.changes.filter(c => !c.isTheirs)
  const theirsChangesInRegion = region.changes.filter(c => c.isTheirs)

  let mineResolved, theirsResolved, baseResolved

  // Get the lines for this region
  baseResolved = base.slice(region.baseStart, region.baseEnd)

  if (mineChangesInRegion.length === 0) {
    // Mine didn't change, use base (which is what mine has)
    mineResolved = baseResolved
  } else if (mineChangesInRegion.length === 1) {
    // Single change from mine
    const change = mineChangesInRegion[0]
    mineResolved = mine.slice(change.docStart, change.docEnd)
  } else {
    // Multiple changes from mine - combine them
    const minStart = Math.min(...mineChangesInRegion.map(c => c.docStart))
    const maxEnd = Math.max(...mineChangesInRegion.map(c => c.docEnd))
    mineResolved = mine.slice(minStart, maxEnd)
  }

  if (theirsChangesInRegion.length === 0) {
    // Theirs didn't change, use base
    theirsResolved = baseResolved
  } else if (theirsChangesInRegion.length === 1) {
    // Single change from theirs
    const change = theirsChangesInRegion[0]
    theirsResolved = theirs.slice(change.docStart, change.docEnd)
  } else {
    // Multiple changes from theirs - combine them
    const minStart = Math.min(...theirsChangesInRegion.map(c => c.docStart))
    const maxEnd = Math.max(...theirsChangesInRegion.map(c => c.docEnd))
    theirsResolved = theirs.slice(minStart, maxEnd)
  }

  let resolved
  let isConflict = false
  let regionType = 'stable'

  if (region.changes.length === 1) {
    // Only one side changed
    const change = region.changes[0]
    if (change.isTheirs) {
      resolved = theirsResolved
      regionType = 'theirs'
    } else {
      resolved = mineResolved
      regionType = 'mine'
    }
  } else {
    // Both sides changed
    if (JSON.stringify(mineResolved) === JSON.stringify(theirsResolved)) {
      // Both made the same change
      resolved = mineResolved
      regionType = 'both'
    } else if (JSON.stringify(mineResolved) === JSON.stringify(baseResolved)) {
      // Mine is same as base, so take theirs
      resolved = theirsResolved
      regionType = 'theirs'
    } else if (JSON.stringify(theirsResolved) === JSON.stringify(baseResolved)) {
      // Theirs is same as base, so take mine
      resolved = mineResolved
      regionType = 'mine'
    } else {
      // Conflict - both sides changed differently
      isConflict = true
      resolved = null
    }
  }

  resolvedRegions.push({
    type: regionType,
    resolved,
    isConflict,
    mineLines: mineResolved,
    baseLines: baseResolved,
    theirsLines: theirsResolved,
    lineCount: resolved ? resolved.length : null
  })

  if (isConflict) hasConflict = true
}

// Output based on mode
function outputMerge() {
  const output = []
  for (const region of resolvedRegions) {
    if (region.isConflict) {
      output.push('<<<<<<< mine')
      output.push(...region.mineLines)
      output.push('||||||| base')
      output.push(...region.baseLines)
      output.push('=======')
      output.push(...region.theirsLines)
      output.push('>>>>>>> theirs')
    } else {
      output.push(...region.resolved)
    }
  }
  return output.join('\n') + (output.length > 0 ? '\n' : '')
}

function outputMerge2() {
  const output = []
  for (const region of resolvedRegions) {
    if (region.isConflict) {
      output.push('<<<<<<< mine')
      output.push(...region.mineLines)
      output.push('=======')
      output.push(...region.theirsLines)
      output.push('>>>>>>> theirs')
    } else {
      output.push(...region.resolved)
    }
  }
  return output.join('\n') + (output.length > 0 ? '\n' : '')
}

function outputRegions() {
  const output = []
  for (const region of resolvedRegions) {
    if (region.isConflict) {
      output.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}`)
    } else {
      output.push(`${region.type} ${region.lineCount}`)
    }
  }
  return output.join('\n') + (output.length > 0 ? '\n' : '')
}

if (mode === 'merge') {
  process.stdout.write(outputMerge())
} else if (mode === 'merge2') {
  process.stdout.write(outputMerge2())
} else if (mode === 'regions') {
  process.stdout.write(outputRegions())
}

process.exit(hasConflict ? 1 : 0)
